"""Soundtrack for the demo video. Nothing is recorded or generated by a music model: the app's own sound code
(web/sound.js) is driven with the real NISAR data of two places and rendered offline to video/out/music.wav."""
import asyncio, base64, time, json
from pathlib import Path
from playwright.async_api import async_playwright
OUT = Path(__file__).parent / "out"; OUT.mkdir(exist_ok=True)
CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
T = json.loads((Path(__file__).parent / "timeline.json").read_text())
INIT = """
(() => { // the app asks for an AudioContext; give it an offline one whose clock we set by hand
  const off = new OfflineAudioContext(2, 48000 * %d, 48000); let vt = 1e4;
  // four volume faders (pad, pluck, image scans, kick) so the mix can be balanced without touching the app's sound code
  const comp = off.createDynamicsCompressor(); comp.threshold.value = -20; comp.knee.value = 8; comp.ratio.value = 6; comp.attack.value = 0.004; comp.release.value = 0.16; comp.connect(off.destination);
  const bus = {}, mk = (name, g) => { const n = off.createGain(); n.gain.value = g; n.connect(comp); bus[name] = n; };
  mk("pad", 1.5); mk("pluck", 1.1); mk("scan", 2.4); mk("kick", 0.34); let cur = "pad";
  window.__bus = (n) => { cur = n; }; window.__fade = (name, t0, t1) => { const g = bus[name].gain; g.setValueAtTime(g.value, t0); g.linearRampToValueAtTime(0.0001, t1); };
  const prox = new Proxy(off, { get(t, k) { if (k === "currentTime") return vt; if (k === "destination") return bus[cur]; const v = t[k]; return typeof v === "function" ? v.bind(t) : v; } });
  window.AudioContext = function () { return prox; };
  window.__at = (x) => { vt = x; };
  window.__wav = async () => {
    const buf = await off.startRendering(), L = buf.getChannelData(0), R = buf.getChannelData(1), n = L.length;
    let peak = 0; for (let i = 0; i < n; i++) peak = Math.max(peak, Math.abs(L[i]), Math.abs(R[i]));
    const g = 0.89 / (peak || 1), dv = new DataView(new ArrayBuffer(44 + n * 4)), str = (o, s) => [...s].forEach((c, i) => dv.setUint8(o + i, c.charCodeAt(0)));
    str(0, "RIFF"); dv.setUint32(4, 36 + n * 4, true); str(8, "WAVEfmt "); dv.setUint32(16, 16, true); dv.setUint16(20, 1, true); dv.setUint16(22, 2, true);
    dv.setUint32(24, 48000, true); dv.setUint32(28, 192000, true); dv.setUint16(32, 4, true); dv.setUint16(34, 16, true); str(36, "data"); dv.setUint32(40, n * 4, true);
    for (let i = 0; i < n; i++) { dv.setInt16(44 + i * 4, Math.max(-1, Math.min(1, L[i] * g)) * 32767, true); dv.setInt16(46 + i * 4, Math.max(-1, Math.min(1, R[i] * g)) * 32767, true); }
    const u = new Uint8Array(dv.buffer); let s = ""; for (let i = 0; i < u.length; i += 32768) s += String.fromCharCode.apply(null, u.subarray(i, i + 32768));
    return JSON.stringify({ peak, b64: btoa(s) });
  };
})();
""" % (int(T["total"]) + 1)
SCORE = """
(async () => {
  const T = %s, S = T.scenes, B = T.beat, quiet = () => __at(1e4);
  const grab = async (id) => { quiet(); await loadSite(id); await new Promise((r) => setTimeout(r, 2500)); quiet();
    const f = state.data.frames; return { kind: state.data.kind, scans: f.map((_, i) => scan(i)), water: f.map((x) => x.waterKm2), loss: f.map((x) => x.lossKm2) }; };
  const lake = await grab("tonle-sap"), fire = await grab("shingle"); quiet();
  const w = lake.water, lo = Math.min(...w), hi = Math.max(...w), norm = (v) => (v - lo) / (hi - lo);
  const lossMax = Math.max(...T.firePasses.map((i) => fire.loss[i]));
  const beats = (a, b, step = B) => { const out = []; for (let t = a; t < b - 1e-6; t += step) out.push(+t.toFixed(4)); return out; };
  // Everything sits on a 120 BPM grid (one beat = 0.5 s). All voices are the app's own (web/sound.js).
  // KICK: the app's drum (it plays when the vegetation signal drops) with its low note, on every beat
  const kick = (t, depth = 0.22) => { __bus("kick"); __at(t); Sonify.play("forest", 0, -depth); };
  // PAD: the app's "water" voice; the pitch is the lake's open-water area on one radar pass
  const pad = (t, v) => { __bus("pad"); __at(t); Sonify.play("water", v, 0); };
  // PLUCK: the app's "fields" voice on the off-beats, walking through the lake's 11 passes
  let pk = 0; const pluck = (t) => { __bus("pluck"); __at(t); Sonify.play("crops", norm(w[(pk++ * 3) %% w.length]), 0); };
  // SCAN: the 16 strips of a radar image, left to right, squeezed into `dur` seconds
  const scanAt = (t, site, i, dur) => { __bus("scan"); __at(t); Sonify.playScan(site.kind, site.scans[i], dur); };
  const groove = (a, b, k0 = 0) => { beats(a, b).forEach((t, k) => { kick(t); pluck(t + B / 2); if ((k + k0) %% 2 === 0) pad(t, norm(w[((k + k0) / 2) %% w.length])); }); };

  // intro: pad and off-beat plucks, the drum joins after two beats
  beats(S.globe[0], S.globe[1]).forEach((t, k) => { if (k %% 2 === 0) pad(t, norm(w[k / 2])); pluck(t + B / 2); if (k >= 2) kick(t, k >= 4 ? 0.22 : 0.12); });
  groove(S.clouds[0], S.clouds[1]);
  // flood: one radar pass per beat; the pad follows the real water area, the scan plays that pass's image
  T.waterPasses.forEach((i, k) => { const t = S.water[0] + k * B; scanAt(t, lake, i, B * 0.92); pad(t, norm(w[i])); });
  beats(S.water[0], S.water[1]).forEach((t) => { kick(t); pluck(t + B / 2); });
  // fire: one pass per beat; the note rises with the mapped burn scar
  T.firePasses.forEach((i, k) => { const t = S.fire[0] + k * B; scanAt(t, fire, i, B * 0.92); __bus("pad"); __at(t); Sonify.play("forest", fire.loss[i] / lossMax, 0); });
  beats(S.fire[0], S.fire[1]).forEach((t) => { kick(t); pluck(t + B / 2); });
  // music from the image: the band thins out, each image plays its 16 strips as sixteenth notes over one bar
  const half = (S.music[1] - S.music[0]) / 2;
  scanAt(S.music[0], lake, T.waterPasses.at(-1), half); scanAt(S.music[0] + half, fire, T.firePasses.at(-1), half);
  beats(S.music[0], S.music[1], 2 * B).forEach((t) => kick(t, 0.3));
  groove(S.live[0], S.live[1]); groove(S.montage[0], S.montage[1], 1);
  beats(S.montage[0], S.montage[1]).forEach((t) => kick(t, 0.3)); // the four quick cuts hit harder
  // last chord: lowest, middle and highest lake level together, then the pad rings out
  kick(S.end[0], 0.4); for (const v of [0, 0.45, 1]) { pad(S.end[0], v); pad(S.end[0] + 2 * B, v); }
  pad(S.end[0] + 4 * B, 0); __fade("pad", S.end[0] + 2, T.total - 0.1);
  quiet();
  return JSON.stringify({ ...JSON.parse(await __wav()), scans: { lake: lake.scans.at(-1), fire: fire.scans.at(-1) } });
})()
""" % json.dumps(T)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(headless=True, executable_path=CHROME, args=["--enable-unsafe-swiftshader", "--use-angle=swiftshader", "--autoplay-policy=no-user-gesture-required"])
        page = await (await b.new_context(viewport={"width": 1280, "height": 800})).new_page()
        page.on("pageerror", lambda e: print("PAGEERROR", str(e)[:300]))
        await page.add_init_script(INIT)
        await page.goto(f"http://localhost:8080/?t={int(time.time())}#site=tonle-sap"); await page.wait_for_timeout(4000)
        r = json.loads(await page.evaluate(SCORE))
        (OUT / "music.wav").write_bytes(base64.b64decode(r["b64"]))
        (OUT / "scans.js").write_text("window.SCANS = " + json.dumps(r["scans"]) + ";\nwindow.TL = " + json.dumps(T) + ";\n")
        print("peak before normalising:", round(r["peak"], 3), "bytes:", (OUT / "music.wav").stat().st_size)
        await b.close()
asyncio.run(main())
